Sorry yes that is user defined but it simply outputs the model syntax, based on the RI_CLPM structure described here <a href="https://jeroendmulder.github.io/RI-CLPM/lavaan.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=https://jeroendmulder.github.io/RI-CLPM/lavaan.html&amp;source=gmail&amp;ust=1792415184404000&amp;usg=AOvVaw2YO6YrOg0vonqbn-zK8WMJ">https://jeroendmulder.github.io/RI-CLPM/lavaan.html</a> for example <div><br><div>I pasted the function here for reference (highlighted in red the portion where I set the equality constraints I want to weight </div><div><br></div><div>So for example if you now call </div><div>f = riclpm_formula(&#39;x&#39;, &#39;y&#39;, meas_time=list(c(3, 4.5, 5.2), c(2.9, 4.4, 6)))</div><div>it should print out an example where x was measured at 3, 4.5, and 5.2 years and y was measured at 2.9, 4.4, and 6 years. </div><div><div><br></div><div><span style="background-color:white">riclpm_formula &lt;- function(var1=&#39;dep&#39;, var2=&#39;cmr&#39;,</span></div><div><span style="background-color:white">                                                n_ocs=NULL, meas_time=list(c(), c()),<br>  </span>                                              stationarity=TRUE,</div><div><span style="background-color:white">             </span>                                   verbose=TRUE) {</div><div><span style="background-color:white">  <br>  # Check input ----------------------------------------------------------------<br>  if (is.null(n_ocs) &amp; (length(meas_time[[1]])==0 | length(meas_time[[1]])==0)) { <br>    stop(&#39;Provide total number of occasions or time points of measurement!&#39;) }<br>  <br>  if (length(meas_time[[1]]) != length(meas_time[[2]])) {<br>    stop(&#39;You need the same number of time points for each of the two variables.&#39;) }<br>  <br>  if (!is.null(n_ocs) &amp; !length(meas_time[[1]]) %in% c(0, n_ocs)) { # contraddictory info <br>    stop(&#39;Number of occations and measurement times provided do not agree.&#39;) }<br>  <br>  # ----------------------------------------------------------------------------<br>  # How many occasions <br>  if (length(meas_time[[1]]) &gt; 0) { <br>    temp_var1 = meas_time[[1]]<br>    temp_var2 = meas_time[[2]] <br>  } else { <br>    temp_var1 = temp_var2 = 1:n_ocs <br>  }<br>  <br>  if (is.null(n_ocs)) { n_ocs = length(temp_var1) }<br>  <br>  # Create between components (random intercepts)<br>  random_intercepts = paste0(&#39;# Random intercepts
&#39;,<br>                             &#39;ri_&#39;,var1,&#39; =~ &#39;, paste0(&#39;1*&#39;,var1,1:n_ocs, collapse=&#39; + &#39;), &#39;
&#39;,<br>                             &#39;ri_&#39;,var2,&#39; =~ &#39;, paste0(&#39;1*&#39;,var2,1:n_ocs, collapse=&#39; + &#39;), &#39;
&#39;)<br>  <br>  # Create within-components (or within-person centered variables)<br>  # Note: factor loadings are set to 1 in non-stationary model and freely estimated in stationary models<br>  if (stationarity) { l = &#39;NA*&#39; } else { l = &#39;1*&#39; }<br>  <br>  impulses = paste0(&#39;# Impulses
&#39;,<br>                    paste0(&#39;w_&#39;,var1,1:n_ocs,&#39; =~ &#39;,l,var1,1:n_ocs, collapse=&#39;
&#39;), &#39;
&#39;,<br>                    paste0(&#39;w_&#39;,var2,1:n_ocs,&#39; =~ &#39;,l,var2,1:n_ocs, collapse=&#39;
&#39;), &#39;
&#39;)<br>  <br>  # Estimate lagged effects between within-person centered variables<br>  regressions = &#39;# Regressions
&#39;<br>  for (i in 2:n_ocs) { <br>    # if (n_strata &gt; 1) { ... ar_1 &lt;- paste0(&#39;c(&#39;, paste0(rep(paste0(&#39;AR_&#39;,var1,i-1),strata), collapse=&#39;, &#39;), &#39;)&#39;) #define  strata</span></div><div><span style="background-color:white"><br>    ar_1 &lt;- paste0(&#39;AR_&#39;,var1,i-1)<br>    ar_2 &lt;- paste0(&#39;AR_&#39;,var2,i-1)<br>    cl_1 &lt;- paste0(&#39;CL_&#39;,var1,i-1)<br>    cl_2 &lt;- paste0(&#39;CL_&#39;,var2,i-1)<br>    <br>    regressions = paste0(regressions, <br>      &#39;w_&#39;,var1,i,&#39; ~ &#39;,ar_1,&#39; * w_&#39;,var1,i-1,&#39; + &#39;,cl_1,&#39; * w_&#39;,var2,i-1,&#39;
&#39;,<br>      &#39;w_&#39;,var2,i,&#39; ~ &#39;,ar_2,&#39; * w_&#39;,var2,i-1,&#39; + &#39;,cl_2,&#39; * w_&#39;,var1,i-1,&#39;
&#39;) <br>  }<br>  <br>  # Estimate covariance between within-person centered variables <br>  covariances = paste0(&#39;# Covariances
&#39;,<br>                       # Estimate correlation between within-components at first wave<br>                       &#39;w_&#39;,var1,&#39;1 ~~ cor1 * w_&#39;,var2,&#39;1
&#39;,</span></div><div><span style="background-color:white"><br>                       # Estimate residual covariances (between residuals of within-person vars, i.e., innovations)<br>                       paste0(&#39;w_&#39;,var1,2:n_ocs,&#39; ~~ rcov&#39;,2:n_ocs,&#39; * w_&#39;,var2,2:n_ocs, collapse=&#39;
&#39;), &#39;
&#39;,</span></div><div><span style="background-color:white"><br>                       # Estimate covariance of the random intercepts<br>                       &#39;ri_&#39;,var1,&#39; ~~ covRI * ri_&#39;,var2,&#39;
&#39;)<br>  <br>  if (stationarity) { w1 = &#39;1*&#39; } else { w1 = &#39;&#39; }<br>  <br>  variances = paste0(&#39;# Variances
&#39;,<br>                     # Set variances of within-components at first wave to 1<br>                     paste0(&#39;w_&#39;,var1,&#39;1 ~~ &#39;,w1,&#39;w_&#39;,var1,&#39;1
&#39;, &#39;w_&#39;,var2,&#39;1 ~~ &#39;,w1,&#39;w_&#39;,var2,&#39;1
&#39;),</span></div><div><span style="background-color:white"><br>                     # Estimate (and label) residual variances of within-person centered variables<br>                     paste0(&#39;w_&#39;,var1,2:n_ocs,&#39; ~~ rvar_&#39;,var1,2:n_ocs,&#39;*w_&#39;,var1,2:n_ocs, collapse=&#39;
&#39;),&#39;
&#39;, <br>                     paste0(&#39;w_&#39;,var2,2:n_ocs,&#39; ~~ rvar_&#39;,var2,2:n_ocs,&#39;*w_&#39;,var2,2:n_ocs, collapse=&#39;
&#39;),&#39;
&#39;,</span></div><div><span style="background-color:white"><br>                     # Estimate variance of random intercepts<br>                     &#39;ri_&#39;,var1,&#39; ~~ ri_&#39;,var1,&#39;
ri_&#39;,var2,&#39; ~~ ri_&#39;,var2, &#39;
&#39;)<br>  <br>  constraints = ar_var1_con = ar_var2_con = cl_var1_con = cl_var2_con = cor_con = rvar_con = &#39;&#39;<br>  <br>  if (stationarity) {<br>    constraints = &#39;# Constraints
&#39;<br>      <br>    # paste0(&#39;# Constrain grand means over time
&#39;,<br>    # paste0(var1,1:n_ocs, collapse=&#39; + &#39;), &#39; ~ mean_&#39;,var1,&#39;*1
&#39;,<br>    # paste0(var2,1:n_ocs, collapse=&#39; + &#39;), &#39; ~ mean_&#39;,var2,&#39;*1
&#39;)<br>    <br>    <font color="#ff0000"># Weight for unequal temporal gaps <br>    rel=&#39;^&#39; # &#39;*&#39;<br>    i = 1:(n_ocs-2) # iterator</font></span></div><div>    <span style="background-color:white"><font color="#ff0000">prec=2 # precision<br>    # NOTE: round to nearest integer for the moment <br>    ar_var1_con &lt;- paste0(&#39;AR_&#39;,var1,i,rel,round(temp_var1[i+1]-temp_var1[i], prec), &#39; == AR_&#39;,var1,i+1,rel,round(temp_var1[i+2]-temp_var1[i+1]</font></span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span></div><div><span style="background-color:white"><font color="#ff0000">                          collapse=&#39;
&#39;)<br>    ar_var2_con &lt;- paste0(&#39;AR_&#39;,var2,i,rel,round(temp_var2[i+1]-temp_var2[i]</font></span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span><span style="color:rgb(255,0,0)"> &#39; == AR_&#39;,var2,i+1,rel,round(temp_var2[i+2]-temp_var2[i+1]</span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span></div><div><span style="background-color:white"><font color="#ff0000">                          collapse=&#39;
&#39;)<br>    cl_var1_con &lt;- paste0(&#39;CL_&#39;,var1,i,rel,round(temp_var1[i+1]-temp_var2[i]</font></span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span><span style="color:rgb(255,0,0)"> &#39; == CL_&#39;,var1,i+1,rel,round(temp_var1[i+2]-temp_var2[i+1]</span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span></div><div><span style="background-color:white"><font color="#ff0000">                          collapse=&#39;
&#39;)<br>    cl_var2_con &lt;- paste0(&#39;CL_&#39;,var2,i,rel,round(temp_var2[i+1]-temp_var1[i]</font></span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span><span style="color:rgb(255,0,0)"> &#39; == CL_&#39;,var2,i+1,rel,round(temp_var2[i+2]-temp_var1[i+1]</span><span style="color:rgb(255,0,0)">, prec</span><span style="color:rgb(255,0,0)">),</span></div><div><span style="background-color:white"><font color="#ff0000">                          collapse=&#39;
&#39;)</font><br>    <br>    # Compute correlations between the within-components themselves at each wave<br>    i = 1:(n_ocs-1) # new iterator<br>    cor_con &lt;- paste0(&#39;cor&#39;,2:n_ocs, &#39; := AR_&#39;,var1,i,&#39;*CL_&#39;,var2,i,&#39; + &#39;, &#39;CL_&#39;,var1,i,&#39;*AR_&#39;,var2,i,&#39; + &#39;,  </span></div><div><span style="background-color:white">                                                                  &#39;AR_&#39;,var1,i,&#39;*AR_&#39;,var2,i,&#39;*cor&#39;,i,&#39; + &#39;, &#39;CL_&#39;,var1,i,&#39;*CL_&#39;,var2,i,&#39;*cor&#39;,i,&#39; + rcov&#39;,2:n_ocs, collapse=&#39;
&#39;)<br>    <br>    # Constrain residual variances of within-components such that the total variance of each <br>    # within-component equals 1<br>    rvar_con &lt;- paste0(&#39;rvar_&#39;,var1,2:n_ocs,&#39; == 1 - (AR_&#39;,var1,i,&#39;*AR_&#39;,var1,i,&#39; + &#39;, &#39;CL_&#39;,var1,i,&#39;*CL_&#39;,var1,i,&#39; + 2*AR_&#39;,var1,i,&#39;*CL_&#39;,var1,i,&#39;*cor&#39;,i,&#39;)
&#39;,<br>                                      &#39;rvar_&#39;,var2,2:n_ocs,&#39; == 1 - (AR_&#39;,var2,i,&#39;*AR_&#39;,var2,i,&#39; + &#39;, &#39;CL_&#39;,var2,i,&#39;*CL_&#39;,var2,i,&#39; + 2*AR_&#39;,var2,i,&#39;*CL_&#39;,var2,i,&#39;*cor&#39;,i,&#39;)&#39;, collapse = &#39;
&#39;)<br>  }<br>  <br>  constraints = paste0(constraints, ar_var1_con,&#39;
&#39;, ar_var2_con,&#39;
